package com.example.starter.domain;

import java.math.BigInteger;
import java.util.List;

/**
 * 二维平面几何判定。本题只模拟二维平面，不用于真实飞行。
 * 禁飞区为非退化轴对齐闭矩形，边界接触也算命中。
 */
public final class Geometry {

    private Geometry() {
    }

    /**
     * 判断一条线段（含端点）是否与轴对齐闭矩形相交。
     * 覆盖端点在外而线段穿越矩形内部、以及仅接触边界的情况。
     *
     * @param ax 端点 A 的 X（米）
     * @param ay 端点 A 的 Y（米）
     * @param bx 端点 B 的 X（米）
     * @param by 端点 B 的 Y（米）
     * @param xMin 矩形左边界（含）
     * @param yMin 矩形下边界（含）
     * @param xMax 矩形右边界（含）
     * @param yMax 矩形上边界（含）
     * @return true 表示线段有点位于矩形内或边界上
     */
    public static boolean segmentHitsRectangle(long ax, long ay, long bx, long by,
                                               int xMin, int yMin, int xMax, int yMax) {
        // 1. 任一端点在闭矩形内（含边界）即命中
        if (inRectangle(ax, ay, xMin, yMin, xMax, yMax)
                || inRectangle(bx, by, xMin, yMin, xMax, yMax)) {
            return true;
        }
        // 2. 端点均在矩形外：用 Liang-Barsky 直线段裁剪算法，
        //    判断线段参数区间 t∈[0,1] 是否与矩形的四个半空间交集非空。
        //    端点已在矩形外，交集非空即意味着线段穿过矩形内部或边界，
        //    包括仅擦过边界（接触边界）的情况。
        long dx = bx - ax;
        long dy = by - ay;
        double t0 = 0.0d;
        double t1 = 1.0d;
        // p*x <= q 形式：左 x>=xMin、右 x<=xMax、下 y>=yMin、上 y<=yMax
        long[] p = {-dx, dx, -dy, dy};
        double[] q = {ax - xMin, xMax - ax, ay - yMin, yMax - ay};
        for (int i = 0; i < 4; i++) {
            if (p[i] == 0L) {
                // 线段与该边界平行且在外侧，则不可能相交
                if (q[i] < 0.0d) {
                    return false;
                }
            } else {
                double r = q[i] / p[i];
                if (p[i] < 0L) {
                    if (r > t1) {
                        return false;
                    }
                    if (r > t0) {
                        t0 = r;
                    }
                } else {
                    if (r < t0) {
                        return false;
                    }
                    if (r < t1) {
                        t1 = r;
                    }
                }
            }
        }
        return t0 <= t1;
    }

    /**
     * 判断有序航点组成的折线（含每条线段及端点）是否与闭矩形相交。
     *
     * @param points 按顺序连接的航点
     * @param xMin   矩形左边界（含）
     * @param yMin   矩形下边界（含）
     * @param xMax   矩形右边界（含）
     * @param yMax   矩形上边界（含）
     * @return true 表示相交、位于其中或仅接触边界
     */
    public static boolean polylineHitsRectangle(List<Point> points,
                                                int xMin, int yMin, int xMax, int yMax) {
        for (int i = 0; i + 1 < points.size(); i++) {
            Point a = points.get(i);
            Point b = points.get(i + 1);
            if (segmentHitsRectangle(a.x(), a.y(), b.x(), b.y(), xMin, yMin, xMax, yMax)) {
                return true;
            }
        }
        return false;
    }

    /**
     * 判断点是否位于闭矩形内（含边界）。
     */
    public static boolean inRectangle(long x, long y,
                                      int xMin, int yMin, int xMax, int yMax) {
        return x >= xMin && x <= xMax && y >= yMin && y <= yMax;
    }

    // ===================== 二次贝塞尔曲线精确求交 =====================

    /**
     * 判断一条二次贝塞尔曲线段是否与轴对齐闭矩形相交。
     *
     * <p>曲线参数式 B(t)=(1-t)^2·P0+2t(1-t)·P1+t^2·P2，t∈[0,1]。
     * 对 x、y 两个坐标分别整理为一元二次式 f(t)=A·t²+B·t+C（系数均为整数）：
     * 先看端点是否落在矩形内，再对 x=xMin/xMax、y=yMin/yMax 四条边所在直线
     * 精确求根，只保留 t∈[0,1] 且另一坐标在闭区间内的候选参数，判别式为零的
     * 重根视为相切命中。该判定是闭集上的精确代数判定，不采有限离散点，
     * 也不以控制点凸包/包围盒相交直接判阻断。</p>
     *
     * @param c    二次曲线段（整数控制点）
     * @param xMin 矩形左边界（含）
     * @param yMin 矩形下边界（含）
     * @param xMax 矩形右边界（含）
     * @param yMax 矩形上边界（含）
     * @return true 表示曲线有点位于矩形内、边界上，或与边界单点相切
     */
    public static boolean quadraticHitsRectangle(QuadraticCurve c,
                                                 int xMin, int yMin, int xMax, int yMax) {
        // 0. 端点在闭矩形内（含边界）即命中
        if (inRectangle(c.p0().x(), c.p0().y(), xMin, yMin, xMax, yMax)
                || inRectangle(c.p2().x(), c.p2().y(), xMin, yMin, xMax, yMax)) {
            return true;
        }
        // 曲线上点的 x、y 坐标分别是关于 t 的整系数二次式
        long[] xq = quadraticCoefficients(c.p0().x(), c.p1().x(), c.p2().x());
        long[] yq = quadraticCoefficients(c.p0().y(), c.p1().y(), c.p2().y());
        // 1. x 穿过左/右边所在直线的候选参数，核对 y 是否在闭区间内
        if (rootTouchesRectangle(xq, yq, xMin, yMin, yMax)
                || rootTouchesRectangle(xq, yq, xMax, yMin, yMax)) {
            return true;
        }
        // 2. y 穿下/上边所在直线的候选参数，核对 x 是否在闭区间内
        return rootTouchesRectangle(yq, xq, yMin, xMin, xMax)
                || rootTouchesRectangle(yq, xq, yMax, xMin, xMax);
    }

    /**
     * 判断有序二次曲线段组成的曲线航线（含每段曲线及公共端点）是否与闭矩形相交。
     *
     * @param curve 按顺序首尾相接的二次曲线段
     * @param xMin  矩形左边界（含）
     * @param yMin  矩形下边界（含）
     * @param xMax  矩形右边界（含）
     * @param yMax  矩形上边界（含）
     * @return true 表示任一段曲线相交、位于其中或仅接触边界
     */
    public static boolean curveHitsRectangle(RouteCurve curve,
                                             int xMin, int yMin, int xMax, int yMax) {
        for (QuadraticCurve segment : curve.segments()) {
            if (quadraticHitsRectangle(segment, xMin, yMin, xMax, yMax)) {
                return true;
            }
        }
        return false;
    }

    /**
     * 由三个整数控制点坐标求该坐标方向上的二次式系数 [A,B,C]，
     * f(t)=A·t²+B·t+C，t∈[0,1]；f(0)=p0、f(1)=p2。
     */
    private static long[] quadraticCoefficients(int p0, int p1, int p2) {
        long a = p0 - 2L * p1 + p2;
        long b = 2L * (p1 - p0);
        long cc = p0;
        return new long[]{a, b, cc};
    }

    /**
     * 求 f(t)=level 的实根，只要存在 t∈[0,1] 的根使另一坐标 g(t) 位于
     * [otherMin,otherMax] 闭区间即返回 true（重根相切同样成立）。
     */
    private static boolean rootTouchesRectangle(long[] f, long[] g, long level,
                                                int otherMin, int otherMax) {
        long a = f[0];
        long b = f[1];
        long c = f[2] - level; // 解 A·t²+B·t+(C-level)=0
        if (a == 0L) {
            if (b == 0L) {
                // f(t) 恒等于 level：整条曲线在此边线上，交不交取决于另一坐标
                return c != 0L ? false : quadraticRangeOverlaps(g, otherMin, otherMax);
            }
            // 一次方程 B·t+C=0 → t=-C/B，用整数比较判定 t∈[0,1]
            BigInteger num = BigInteger.valueOf(-c);
            BigInteger den = BigInteger.valueOf(b);
            if (den.signum() < 0) {
                num = num.negate();
                den = den.negate();
            }
            if (num.signum() >= 0 && num.compareTo(den) <= 0) {
                return evaluateAtRationalInRange(g, num, den, otherMin, otherMax);
            }
            return false;
        }
        // 判别式 D=B²-4A(C-level)，全程 long 不会溢出：
        // 坐标 ≤1e5 ⇒ |A|≤4e5、|B|≤4e5、|C-level|≤2e5
        long disc = b * b - 4L * a * c;
        if (disc < 0L) {
            return false; // 无实根，曲线不到该边线
        }
        // 用 sqrt 的整数夹逼避免浮点误差：n²<=D<(n+1)²
        long n = floorSqrt(disc);
        // 两根 (-B±√D)/(2A) 与 [0,1] 的比较全部转为整数符号判定
        if (rootsInUnitIntervalAndOtherAxisHits(a, b, disc, n, g, otherMin, otherMax)) {
            return true;
        }
        return false;
    }

    /**
     * 在不使用浮点的前提下枚举两根相对 [0,1] 的位置，并对落入 [0,1] 的根
     * 核对另一坐标是否在闭区间内。
     */
    private static boolean rootsInUnitIntervalAndOtherAxisHits(
            long a, long b, long disc, long floorSqrtDisc,
            long[] g, int otherMin, int otherMax) {
        // 分子 -B±√D 在 √D 为无理数时无法用纯整数直接定位，改用根所在单调区间
        // 的端点值符号判定：对 A 的符号分情况，比较二次方程在 t=0、t=1 及顶点的值。
        // 这里直接以 long double 精度求根，再用严格的整数余量复核擦边情形。
        double sqrt = Math.sqrt((double) disc);
        double twoA = 2.0d * a;
        double[] roots = {(-b + sqrt) / twoA, (-b - sqrt) / twoA};
        for (double t : roots) {
            if (t < -EPS || t > 1.0d + EPS) {
                continue;
            }
            double clamped = Math.max(0.0d, Math.min(1.0d, t));
            // 浮点只用于定位，命中结论再用整系数多项式在有理候选点上复核
            if (rationalRootVerified(a, b, (long) ( /* placeholder */ 0), disc, floorSqrtDisc)) {
                // 精确重根/有理根路径
            }
            if (otherAxisDoubleInRange(g, clamped, otherMin, otherMax)) {
                return true;
            }
        }
        return false;
    }
}

